package moe.cangku.reader;
import android.app.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

/** Independent follows, bound to the existing verified website UID. No polling or website writes. */
final class SocialFollowScreens {
 final MainActivity host;final ChatVault vault;final ChatClient api=new ChatClient(ServiceEndpoint.origin());final Map<Long,JSONObject> authors=new HashMap<>();
 SocialFollowScreens(MainActivity h){host=h;vault=new ChatVault(h,"privateIdentity","cangku.private.v1");}
 Ui ui(){return host.design();}long uid(){return host.account()==null?0:host.account().optLong("id");}
 String token(){JSONObject session=vault.load(uid(),ServiceEndpoint.origin());try{if(session!=null&&session.getJSONObject("user").getLong("id")==uid()&&java.time.Instant.parse(session.getString("expires_at")).toEpochMilli()>System.currentTimeMillis())return session.getString("token");}catch(Exception ignored){}return "";}
 AlertDialog.Builder dialog(){return new AlertDialog.Builder(new android.view.ContextThemeWrapper(host,ui().dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert));}
 void identify(Runnable next){if(!token().isEmpty()){next.run();return;}long owner=uid();dialog().setTitle("认证仓库账号").setMessage("关注、粉丝与动态使用星屿独立服务，手机和电脑共享；官网网页不会同步。认证时临时将当前官网会话交给服务核验UID，不保存密码或会话。").setNegativeButton("取消",null).setPositiveButton("认证并继续",(d,w)->host.task(()->host.client().enablePrivateMessaging(owner),session->{if(uid()!=owner)return;vault.save(owner,ServiceEndpoint.origin(),session);next.run();},host::toast)).show();}
 void gate(){LinearLayout body=host.content();TextView title=ui().text("和喜欢的作者保持联系",22,ui().text,true);body.addView(title);ui().space(body,12);body.addView(ui().text("认证仓库账号后同步关注与粉丝，在这里查看关注作者的新投稿。",14,ui().muted,false));ui().space(body,18);body.addView(ui().button("认证仓库账号",true,()->identify(host::reloadNative)));}
 JSONObject request(String path,JSONObject body,String secret)throws Exception{long account=uid();try{return api.request("/dm/v1/"+path,body,secret,false);}catch(ChatClient.Failure e){if(e.status==401&&uid()==account){JSONObject saved=vault.load(account,ServiceEndpoint.origin());if(saved!=null&&secret.equals(saved.optString("token")))vault.clear(account);}throw e;}}
 void clear(){authors.clear();}
 void counts(LinearLayout parent){
  LinearLayout row=ui().row();row.setBackground(ui().round(ui().surface,18));TextView follow=ui().button("—\n关注",false,()->host.socialPeople(false,1)),fans=ui().button("—\n粉丝",false,()->host.socialPeople(true,1));row.addView(follow,new LinearLayout.LayoutParams(0,-2,1));row.addView(fans,new LinearLayout.LayoutParams(0,-2,1));parent.addView(row);ui().space(parent,14);String secret=token();if(!secret.isEmpty())host.task(()->request("follows/status",null,secret),r->{follow.setText(r.optInt("following_count")+"\n关注");fans.setText(r.optInt("follower_count")+"\n粉丝");},e->{follow.setText("查看关注");fans.setText("查看粉丝");});
 }
 void authorControls(LinearLayout parent,JSONObject author){authorControls(parent,author,null,null);}
 void authorControls(LinearLayout parent,JSONObject author,Boolean initialFollowing,Boolean initialMutual){
  long id=author.optLong("id"),owner=uid();authors.put(id,author);if(id<=0||id==uid())return;TextView button=ui().button("＋ 关注作者",true,()->{});parent.addView(button,new LinearLayout.LayoutParams(-1,-2));ui().space(parent,8);TextView hint=ui().text("星屿独立关注 · 手机与电脑共享",11,ui().muted,false);parent.addView(hint);ui().space(parent,14);
  final boolean[] followed={Boolean.TRUE.equals(initialFollowing)},mutual={Boolean.TRUE.equals(initialMutual)},loaded={initialFollowing!=null};if(loaded[0])button.setText(followed[0]?(mutual[0]?"互相关注":"已关注"):(mutual[0]?"回关":"＋ 关注作者"));String secret=token();if(!secret.isEmpty()&&!loaded[0])host.task(()->request("follows/status?peer="+id,null,secret),r->{followed[0]=r.optBoolean("following");mutual[0]=r.optBoolean("follows_you");loaded[0]=true;button.setText(followed[0]?(mutual[0]?"互相关注":"已关注"):(mutual[0]?"回关":"＋ 关注作者"));hint.setText("星屿粉丝 "+r.optInt("follower_count")+" · 官网网页不跟随变化");},e->hint.setText("关注状态暂未同步，点击可重试"));
  button.setOnClickListener(v->{if(uid()!=owner)return;identify(()->{
   Runnable change=()->{if(uid()!=owner)return;button.setEnabled(false);String key=token();boolean next=!followed[0];host.task(()->request("follows",new JSONObject().put("peer_id",id).put("following",next),key),r->{followed[0]=next;button.setEnabled(true);button.setText(next?(mutual[0]?"互相关注":"已关注"):(mutual[0]?"回关":"＋ 关注作者"));hint.setText(next?"已关注，新投稿会出现在动态中":"已取消关注");},e->{button.setEnabled(true);host.toast(e);});};
   Runnable confirm=()->{if(followed[0])dialog().setTitle("取消关注？").setMessage("取消后，该作者的新投稿将不再出现在动态中。").setNegativeButton("返回",null).setPositiveButton("取消关注",(d,w)->change.run()).show();else change.run();};
   if(loaded[0])confirm.run();else{button.setEnabled(false);host.task(()->request("follows/status?peer="+id,null,token()),r->{button.setEnabled(true);followed[0]=r.optBoolean("following");mutual[0]=r.optBoolean("follows_you");loaded[0]=true;confirm.run();},e->{button.setEnabled(true);host.toast(e);});}
  });});
 }
 void people(boolean followers,int page){
  host.toolbar(followers?"我的粉丝":"我的关注",true,host::reloadNative);if(token().isEmpty()){gate();return;}LinearLayout body=host.content();body.addView(ui().text("星屿独立关注 · 与电脑端同步",12,ui().muted,false));TextView status=ui().text("正在同步…",14,ui().muted,false);body.addView(status);String key=token();
  host.task(()->{JSONObject r=request("follows?kind="+(followers?"followers":"following")+"&page="+page,null,key);JSONArray list=r.optJSONArray("users");if(list!=null)for(int i=0;i<list.length();i++){JSONObject user=list.getJSONObject(i);boolean state=user.optBoolean("following"),mutual=user.optBoolean("follows_you");try{JSONObject canonical=host.client().get("user/info",ApiClient.params("id",user.optString("id"))).getJSONObject("data");if(canonical.optLong("id")==user.optLong("id")){Iterator<String> keys=canonical.keys();while(keys.hasNext()){String k=keys.next();user.put(k,canonical.opt(k));}}}catch(Exception ignored){}user.put("following",state).put("follows_you",mutual);}return r;},r->{body.removeView(status);JSONArray list=r.optJSONArray("users");if(list==null||list.length()==0){body.addView(ui().text("这里还很安静，去作者主页关注喜欢的创作者吧。",14,ui().muted,false));if(page>1)body.addView(ui().button("返回第一页",false,()->host.socialPeople(followers,1)));return;}
   for(int i=0;i<list.length();i++){JSONObject user=list.optJSONObject(i);authors.put(user.optLong("id"),user);LinearLayout card=ui().column();ui().pad(card,14,14,14,14);card.setBackground(ui().round(ui().surface,18));LinearLayout line=ui().row();line.addView(avatar(user,46),new LinearLayout.LayoutParams(ui().dp(46),ui().dp(46)));LinearLayout names=ui().column();ui().pad(names,12,0,0,0);names.addView(ui().text(user.optString("nickname"),16,ui().text,true));names.addView(ui().text("UID "+user.optLong("id"),11,ui().muted,false));line.addView(names,new LinearLayout.LayoutParams(0,-2,1));ui().click(line,()->host.navigateNative("profile","作者主页",user.optLong("id")));card.addView(line);ui().space(card,12);authorControls(card,user,user.optBoolean("following"),user.optBoolean("follows_you"));body.addView(card);ui().space(body,12);}
   int total=r.optInt("total_pages",1);LinearLayout paging=ui().row();TextView prev=ui().button("上一页",false,()->host.socialPeople(followers,page-1)),next=ui().button("下一页",false,()->host.socialPeople(followers,page+1));prev.setEnabled(page>1);next.setEnabled(page<total);paging.addView(prev,new LinearLayout.LayoutParams(0,-2,1));paging.addView(ui().text(page+" / "+total,12,ui().muted,false));paging.addView(next,new LinearLayout.LayoutParams(0,-2,1));body.addView(paging);
  },e->{status.setText(e);body.addView(ui().button("重试 / 重新认证",false,()->{vault.clear(uid());identify(host::reloadNative);}));});
 }
 String date(String value){try{return java.time.OffsetDateTime.parse(value).atZoneSameInstant(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("MM-dd HH:mm"));}catch(Exception e){return value;}}
 ImageView avatar(JSONObject user,int size){ImageView image=new ImageView(host);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(ui().round(ui().soft,size/2));image.setClipToOutline(true);image.setContentDescription(user.optString("nickname","作者"));host.pictures().into(user.optString("avatar"),image);return image;}
 void feed(long selected,int page){
  host.toolbar("关注动态",false,host::reloadNative);if(token().isEmpty()){gate();return;}LinearLayout body=host.content();TextView status=ui().text("正在寻找关注作者的新作品…",14,ui().muted,false);body.addView(status);String key=token();
  host.task(()->{JSONObject r=request("follows/ids",null,key);JSONArray ids=r.optJSONArray("ids");Set<Long> followed=new HashSet<>();if(ids!=null)for(int i=0;i<ids.length();i++)followed.add(ids.optLong(i));long active=followed.contains(selected)?selected:0;JSONArray posts=new JSONArray();int next=page;boolean more=!followed.isEmpty();for(int scan=0;scan<(active>0?1:3)&&more;scan++){
    Map<String,String> params=ApiClient.params("page",String.valueOf(next),"per_page","24","simple","1","include","user,categories:simple","with[0]","user","with[1]","categories","order_by","created_at","order","desc");if(active>0)params.put("user_id",String.valueOf(active));JSONObject batch=host.client().get("post/list",params);JSONArray values=batch.optJSONArray("data");if(values!=null)for(int i=0;i<values.length();i++){posts.put(values.getJSONObject(i));}JSONObject pagination=batch.optJSONObject("meta")==null?null:batch.optJSONObject("meta").optJSONObject("pagination");more=pagination!=null&&next<pagination.optInt("total_pages");next++;
   }return r.put("posts",FollowFeedRules.select(posts,followed,active)).put("next_page",next).put("has_more",more).put("active",active);},r->{body.removeView(status);LinearLayout head=ui().column();ui().pad(head,14,14,14,14);head.setBackground(ui().round(ui().surface,20));LinearLayout title=ui().row();title.addView(ui().text("只看关注的作者",17,ui().text,true),new LinearLayout.LayoutParams(0,-2,1));title.addView(ui().button("管理关注",false,()->host.socialPeople(false,1)));head.addView(title);
   HorizontalScrollView strip=new HorizontalScrollView(host);strip.setHorizontalScrollBarEnabled(false);LinearLayout people=ui().row();people.addView(ui().chip("全部动态",r.optLong("active")==0,()->host.socialFeed(0,1)));JSONArray peers=r.optJSONArray("authors");if(peers!=null)for(int i=0;i<peers.length();i++){JSONObject a=peers.optJSONObject(i);JSONObject cached=authors.get(a.optLong("id"));if(cached!=null)a=cached;final JSONObject person=a;LinearLayout item=ui().column();item.setGravity(Gravity.CENTER);ui().pad(item,10,4,10,4);item.addView(avatar(a,42),new LinearLayout.LayoutParams(ui().dp(42),ui().dp(42)));TextView name=ui().text(a.optString("nickname","UID "+a.optLong("id")),10,ui().muted,false);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);item.addView(name,new LinearLayout.LayoutParams(ui().dp(58),-2));ui().click(item,()->host.socialFeed(person.optLong("id"),1));people.addView(item);}strip.addView(people);head.addView(strip);body.addView(head);ui().space(body,16);
   JSONArray posts=r.optJSONArray("posts");if(posts==null||posts.length()==0){body.addView(ui().text(r.optJSONArray("ids").length()==0?"关注第一位作者，让下一次更新不再错过。":"这段时间暂未发现投稿，可选择作者或继续向前查找。",14,ui().muted,false));body.addView(ui().button("发现作者",false,host::discoverAuthors));}
   if(posts!=null)for(int i=0;i<posts.length();i++){JSONObject post=posts.optJSONObject(i),author=post.optJSONObject("user");if(author==null)author=new JSONObject();authors.put(author.optLong("id"),author);final JSONObject who=author;LinearLayout card=ui().column();ui().pad(card,16,16,16,16);card.setBackground(ui().round(ui().surface,20));LinearLayout by=ui().row();by.addView(avatar(author,42),new LinearLayout.LayoutParams(ui().dp(42),ui().dp(42)));LinearLayout names=ui().column();ui().pad(names,12,0,0,0);names.addView(ui().text(author.optString("nickname","仓库作者"),15,ui().text,true));names.addView(ui().text(date(post.optString("created_at"))+" · 发布了新作品",10,ui().muted,false));by.addView(names,new LinearLayout.LayoutParams(0,-2,1));ui().click(by,()->host.navigateNative("profile","作者主页",who.optLong("id")));card.addView(by);ui().space(card,12);TextView name=ui().text(post.optString("title"),17,ui().text,true);name.setLineSpacing(ui().dp(3),1.1f);card.addView(name);ui().space(card,12);ImageView cover=new ImageView(host);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setBackground(ui().round(ui().soft,14));cover.setClipToOutline(true);card.addView(cover,new LinearLayout.LayoutParams(-1,ui().dp(210)));host.pictures().into(post.optString("thumb"),cover);ui().space(card,10);card.addView(ui().button("查看作品  →",false,()->host.navigateNative("article","作品详情",post.optLong("id"))));body.addView(card);ui().space(body,16);}
   if(r.optBoolean("has_more"))body.addView(ui().button("继续查找更早动态",true,()->host.socialFeed(selected,r.optInt("next_page",1))));if(page>1)body.addView(ui().button("回到最新",false,()->host.socialFeed(selected,1)));ui().space(body,12);body.addView(ui().text("动态来自官网投稿，全部动态每次按时间检索最多3页，未找到时可继续向前查找。",11,ui().muted,false));
  },e->{status.setText(e);body.addView(ui().button("重试 / 重新认证",false,()->{vault.clear(uid());identify(host::reloadNative);}));});
 }
}
